<aside class="journal-sidebar" aria-label="Journal topics and recent articles"><section><span class="eyebrow">EXPLORE BY TOPIC</span><h2>Categories</h2><nav class="journal-categories" aria-label="Journal categories"><a href="<?= url('blog').'?'.http_build_query(['q'=>$query,'tag'=>$tag]) ?>" <?= !$categoryId?'aria-current="true"':'' ?>>All topics <?= icon('arrow-right-up-line') ?></a><?php foreach($blogCategories as $cat): ?><a href="<?= url('blog').'?'.http_build_query(['category'=>$cat['id'],'q'=>$query,'tag'=>$tag]) ?>" <?= $categoryId===(int)$cat['id']?'aria-current="true"':'' ?>><span><?= e($cat['name']) ?></span><small><?= $cat['post_count'] ?></small></a><?php endforeach ?></nav></section><section><span class="eyebrow">FROM THE JOURNAL</span><h2>Recent articles</h2><?php foreach($recentPosts as $post): ?><a class="journal-recent" href="<?= url('blog/'.$post['slug']) ?>"><img src="<?= photo($post['thumbnail']) ?>" alt="<?= e($post['image_alt']) ?>" loading="lazy" width="76" height="64"><span><strong><?= e($post['title']) ?></strong><small><?= date('d M Y',strtotime($post['published_at'])) ?></small></span></a><?php endforeach ?></section><?php if($tagCloud): ?><section><span class="eyebrow">FOLLOW YOUR INTEREST</span><h2>Popular tags</h2><nav class="journal-tags" aria-label="Article tags"><?php foreach($tagCloud as $label=>$count): ?><a href="<?= url('blog').'?'.http_build_query(['tag'=>$label,'q'=>$query,'category'=>$categoryId]) ?>" <?= strcasecmp($tag,$label)===0?'aria-current="true"':'' ?>><?= e($label) ?><span><?= $count ?></span></a><?php endforeach ?></nav></section><?php endif ?><div class="journal-help"><?= icon('customer-service-2-line') ?><h2>Questions about equipment?</h2><p>Let’s talk through your requirements.</p><a class="text-link" href="<?= url('contact') ?>">Speak to our team <?= icon('arrow-right-line') ?></a></div></aside>
